use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Enumerates the different kinds of macro invocations."] # [doc = ""] # [doc = " Each variant corresponds to a different syntax and behavior for calling macros."] # [derive (Debug)] pub enum InvocationKind { # [doc = " A function-like macro invocation, e.g., `vec![1, 2, 3]`."] Bang { mac : Box < ast :: MacCall > , span : Span , } , # [doc = " An attribute-like macro invocation, e.g., `#[derive(Debug)]`."] Attr { attr : ast :: Attribute , # [doc = " Re-insertion position for inert attributes."] pos : usize , item : Annotatable , # [doc = " Required for resolving derive helper attributes."] derives : Vec < ast :: Path > , } , # [doc = " A `derive` macro invocation, e.g., `#[derive(Debug)]`."] # [doc = " This is distinct from `Attr` because `derive` macros have special handling."] Derive { path : ast :: Path , is_const : bool , item : Annotatable , } , # [doc = " A glob delegation macro, used for specialized trait implementations."] GlobDelegation { item : Box < ast :: AssocItem > , # [doc = " Whether this is a trait impl or an inherent impl."] of_trait : bool , } , }